    for _ in range(n):
        k = int(data[idx])
        idx += 1
        faces = data[idx:idx + k]
        idx += k
        dice.append((k, Counter(faces)))

    ans = 0.0

    for i in range(n):
        ki, ci = dice[i]
        for j in range(i + 1, n):
            kj, cj = dice[j]

            if len(ci) <= len(cj):
